@module bridge  src=bridge.lua  loc=213  mode=chunk  self=bridge

# Invariants & contracts
  @contract  tick() is the only entry; execute/render/scan are internal. Deps: { env, spoolDir? }.  @ 3
  @invariant  a bad chunk never escapes — load failure and runtime error both land in the res file  @ 4
  @invariant  request file is read then deleted BEFORE execute, so a mid-chunk crash cannot replay it  @ 5
  @invariant  chunk env = deps.env over a _G fallback (stdlib+reaper); chunk global writes stay in env  @ 6
  @invariant  dormant until the spool dir exists (re-stat ~60 frames); once enabled, stays enabled  @ 7
  @reaper  EnumerateFiles caches per-dir; each scan invalidates with idx -1, else stale/deleted reqs linger  @ 8

# Shapes
  @shape  response = "status: ok|error\nms: N\n--- value ---\n<render>\n--- print ---\n<buffered>\n"  @ 9

# Imports
  @require util = 'util'  @ 11

# Private state
  @state deps = ... or {}  @ 13
  @state env = deps.env or {}  @ 14
  @state spoolDir = deps.spoolDir or defaultSpoolDir()  @ 23
  @state printBuf = {}  @ 27
  @state DEFAULTS = { depth = 4, entries = 40, str = 200, total = 64 * 1024 }  @ 65
  @state CAP = {}  @ 66   -- sentinel thrown when the total byte cap is exceeded
  @state bridge = {}  @ 200
  @state enabled, cooldown = false, 0  @ 201

# Private functions
  @fn defaultSpoolDir()  @ 19-22
  -- Small IO
  @fn join(name)  @ 36
  @fn readAll(path)  @ 38-41
  @fn writeAtomic(path, text)  @ 43-48
  @fn dirExists(path)  @ 50-53
  @fn nowMs()  @ 55-58
  -- Render
  @fn render(value, opts)  @ 68-117
  -- Directives
  @fn parseDirectives(code)  @ 121-133
  -- Execute
  @fn execute(rawCode)  @ 137-162
  @fn formatResponse(r)  @ 164-171
  -- Scan
  @fn firstReq()  @ 175-186
  @fn scanOnce()  @ 188-195

# Functions held in tables
  @held env.print(...)  @ 28-32

# Public API (bridge:*)
  @api bridge:tick()  @ 203-211

# Uses (outbound edges)
  @use call    util.add  @ env.print:31 render:79,113
  @use require util  @ <load>:11

# Calls (intra-file)
  @call defaultSpoolDir  @ <load>:23
  @call dirExists  @ tick:207
  @call execute  @ scanOnce:194
  @call firstReq  @ scanOnce:189
  @call formatResponse  @ scanOnce:194
  @call join  @ scanOnce:192,193,194
  @call nowMs  @ execute:140,159
  @call parseDirectives  @ execute:139
  @call readAll  @ scanOnce:192
  @call render  @ execute:154
  @call scanOnce  @ tick:210
  @call writeAtomic  @ scanOnce:194

# Unresolved receivers
  @drop body:match  @ parseDirectives:127
  @drop code:match  @ parseDirectives:124
  @drop f:close  @ readAll:40 writeAtomic:46 dirExists:51
  @drop f:match  @ firstReq:183
  @drop f:read  @ readAll:40
  @drop f:write  @ writeAtomic:46
  @drop line:match  @ parseDirectives:125
  @drop name:match  @ scanOnce:191
  @drop source:match  @ defaultSpoolDir:20
  @drop v:sub  @ render:102

# REAPER API surface
  @reaper time_precise
  @reaper Undo_BeginBlock, Undo_EndBlock2
  @reaper EnumerateFiles

# Fields (r read / w write incl. constructor keys)
  @field r Undo_BeginBlock  @ execute:147
  @field r Undo_EndBlock2  @ execute:149
  @field w __index  @ 17
  @field r depth  @ render:70
  @field w depth  @ 65
  @field r entries  @ render:71
  @field w entries  @ 65
  @field r env  @ 14
  @field r ms  @ formatResponse:167
  @field w ms  @ execute:159
  @field r n  @ execute:152,153
  @field r print  @ formatResponse:169
  @field w print  @ env.print:28 execute:160
  @field r source  @ defaultSpoolDir:20
  @field r spoolDir  @ 23
  @field r status  @ formatResponse:166
  @field w status  @ execute:144,154,156
  @field r str  @ render:72
  @field w str  @ 65
  @field r time_precise  @ nowMs:56
  @field r total  @ render:73
  @field w total  @ 65
  @field r traceback  @ execute:148
  @field r undo  @ execute:146
  @field w undo  @ parseDirectives:128
  @field r value  @ formatResponse:168
  @field w value  @ execute:144,154,156
